class GraphSearch:

    def find_path(self, graph, start, goal):
        path = []
        seen = set()
        seen.add(start)
        current = start
        while current != goal:
            if current not in graph:
                return None
            neighbors = graph.get(current, [])
            for neighbor in neighbors:
                if neighbor not in seen:
                    seen.add(neighbor)
                    path.append(neighbor)
                    if neighbor == goal:
                        return path
            current = path[-1]
        return None
